        <button
          type="button"
          onClick={addSection}
          className="mt-5 inline-flex items-center gap-2 rounded-xl border border-indigo-200 bg-indigo-50 px-4 py-2.5 text-sm font-bold text-indigo-700 transition hover:bg-indigo-100"
        >
          <Plus className="h-4 w-4" />
          Add section
